-- The "Information about <event>" box that some events show above their PaperCept "Submit a contribution" table
-- (venues.details.schedule.info: title, last updated, paragraphs and lists). Events without one are left unchanged.
update venues set details = jsonb_set(details, '{schedule,info}', '{"title": "Information about AdCONIP 2026", "updated": "December 13, 2019", "blocks": [{"text": "All papers must be submitted electronically through the PaperCept Conference Management System. Authors are advised to read PaperCept''s Getting Started Manual for Authors."}, {"text": "The paper format requirements are as follows:"}, {"list": ["Page limit: 6 pages.", "Language: English.", "Paper size: A4.", "Paper format: Two-column format PDF files in the standard conference style. Please refer PaperCept''s Getting Started Manual for Authors to prepare your manuscript.", "Maximum file size: 2MB.", "Please submit your final camera-ready papers through the PaperCept Conference Management System before the submission deadline.", "The author of accepted papers must pay the registration fee simultaneously through Registration Management System. The author can upload a maximum two camera-ready papers at no extra charge."]}]}'::jsonb) where slug = 'adconip-2026' and details ? 'schedule';
update venues set details = jsonb_set(details, '{schedule,info}', '{"title": "Information about ICSTCC 2026", "updated": "May 12, 2026", "blocks": [{"text": "For preparing the first version of your paper, please closely follow the detailed instructions given in the webpage https://icstcc.org/2026/initial-papers-submission/"}]}'::jsonb) where slug = 'icstcc-2026' and details ? 'schedule';
update venues set details = jsonb_set(details, '{schedule,info}', '{"title": "Information about ISCS 2027", "updated": "July 22, 2022", "blocks": [{"text": "Two categories of paper submissions are provided for authors:"}, {"list": ["Regular paper: Submit a full paper of a completed work up to 8 pages in the symposium format for review. According to the review result, a regular paper may be moved to the position paper category. The final manuscript is required to be also in the symposium format within 8 pages. The accepted regular papers will be included in the IEEE Xplore subject to meeting IEEE Xplore''s scope and quality requirements.", "Position paper: Submit an extended abstract up to 8 pages in the symposium format for review. The final manuscript can be also in the symposium format within 8 pages. Papers in this category will not be included in the IEEE Xplore."]}, {"text": "All of the papers for both initial and final submissions must be in English."}]}'::jsonb) where slug = 'iscs-2027' and details ? 'schedule';
update venues set details = jsonb_set(details, '{schedule,info}', '{"title": "Information about ICUAS 2027", "updated": "July 14, 2021", "blocks": [{"text": "You may upload"}, {"list": ["PDF created on your own platform", "MS-Word file", "LaTeX source files - in this case zip all files including style files together and name the main file as root.tex"]}]}'::jsonb) where slug = 'icuas-2027' and details ? 'schedule';
